void dei_ask_handler_wake( Wake_Status wake_status )
{		
  	dei_ask_bit_time_set(); 

	switch( wake_status )  
	{
		case s_WAKE : dei_ask_fiq_mode_leave();break;
		case s_SLEEP: dei_ask_fiq_mode_enter();break;
		
        default:break;
	}  	    
}

